public function Activated()
{
    local BioWorldInfo World;
    local SFXGame Game;
    local BioPlayerController PC;
    local SFXPawn_Player Player;
    local BioGlobalVariableTable VarTable;
    local TD LevelTreasure;
    local SFXInventoryManager Inventory;
    local SFXEngine Eng;
    local string MissionName;

    World = BioWorldInfo(Class'Engine'.static.GetCurrentWorldInfo());
    Game = SFXGame(World.Game);
    PC = World.GetLocalPlayerController();
    Player = SFXPawn_Player(PC.Pawn);
    VarTable = World.GetGlobalVariables();
    Eng = SFXEngine(Class'Engine'.static.GetEngine());
    Inventory = SFXInventoryManager(PC.Pawn.InvManager);
    if (World == None || Game == None || PC == None || Player == None || VarTable == None || Inventory == None || Eng == None)
    {
        OutputLinks[1].bHasImpulse = TRUE;
        return;
    }
    MissionName = World.GetMapName();
    RewardAmount = FClamp(RewardAmount, 0.0, 1.0);
    foreach Game.TREASURE.LevelTreasure(LevelTreasure, )
    {
        if (Locs(LevelTreasure.Level) == Locs(MissionName))
        {
            if (Game.AwardXP(int(float(LevelTreasure.XP) * RewardAmount), LevelTreasure.Level) == TRUE)
            {
                OutputLinks[0].bHasImpulse = TRUE;
            }
            else
            {
                OutputLinks[1].bHasImpulse = TRUE;
            }
            return;
        }
    }
    OutputLinks[1].bHasImpulse = TRUE;
}

public function Used(Actor User)
{
    local SFXEngine Engine;

    Engine = SFXEngine(Class'Engine'.static.GetEngine());
    if (Engine != None && !HasBeenUsed() && UseModuleGUID.A != 0 && UseModuleGUID.B != 0 && UseModuleGUID.C != 0 && UseModuleGUID.D != 0)
    {
        Engine.UseModuleList.AddItem(UseModuleGUID);
    }
}

public function bool HasBeenUsed()
{
    local SFXEngine Engine;
    local Guid CurrentGUID;

    Engine = SFXEngine(Class'Engine'.static.GetEngine());
    if (Engine != None)
    {
        foreach Engine.UseModuleList(CurrentGUID, )
        {
            if (UseModuleGUID == CurrentGUID)
            {
                return TRUE;
            }
        }
    }
    return FALSE;
}

public final function bool UnlockGAWAsset(int Id)
{
    local int AssetIdx;
    local int idx;
    local int Idx2;
    local BioWorldInfo MyWorldInfo;
    local SFXGame MyGame;
    local SFXEngine MyEngine;
    local float CalculatedStartingStrength;
    local GAWAssetSaveInfo NewGAWAsset;
    local BioGlobalVariableTable VarTable;
    local BioRemoteLogger GLogger;
    local BioPlayerController PC;
    local BioHintSystem HintSystem;

    MyWorldInfo = BioWorldInfo(Class'Engine'.static.GetCurrentWorldInfo());
    if (MyWorldInfo == None)
    {
        return FALSE;
    }
    MyGame = SFXGame(MyWorldInfo.Game);
    if (MyGame == None)
    {
        return FALSE;
    }
    MyEngine = SFXEngine(Class'Engine'.static.GetEngine());
    if (MyEngine == None)
    {
        return FALSE;
    }
    VarTable = MyWorldInfo.GetGlobalVariables();
    if (VarTable == None)
    {
        return FALSE;
    }
    PC = BioPlayerController(MyWorldInfo.GetALocalPlayerController());
    if (PC == None)
    {
        return FALSE;
    }
    HintSystem = BioHintSystem(PC.HintSystem);
    if (HintSystem == None)
    {
        return FALSE;
    }
    AssetIdx = AllAssets.Find('Id', Id);
    if (AssetIdx < 0)
    {
        return FALSE;
    }
    if (IsGAWAssetUnlocked(AllAssets[AssetIdx].Id))
    {
        return FALSE;
    }
    CalculatedStartingStrength = float(AllAssets[AssetIdx].StartingStrength);
    for (idx = 0; idx < AllAssets.Length; idx++)
    {
        if (AllAssets[idx].Type == EGAWAssetType.GAWAssetType_Modifier && IsGAWAssetUnlocked(AllAssets[idx].Id) == TRUE)
        {
            for (Idx2 = 0; Idx2 < AllAssets[idx].ModTargets.Length; Idx2++)
            {
                if (AllAssets[idx].ModTargets[Idx2].TargetID == Id)
                {
                    CalculatedStartingStrength += float(AllAssets[idx].ModTargets[Idx2].Value);
                }
            }
        }
    }
    NewGAWAsset.Id = AllAssets[AssetIdx].Id;
    NewGAWAsset.Strength = int(CalculatedStartingStrength);
    UnlockedGAWAssets.AddItem(NewGAWAsset);
    if (AllAssets[AssetIdx].Type == EGAWAssetType.GAWAssetType_Salvage)
    {
        GiveGAWCreditsForAsset(AllAssets[AssetIdx].Id);
    }
    foreach AllAssets[AssetIdx].UnlockPlotStates(idx, )
    {
        VarTable.SetBool(idx, TRUE);
    }
    if (AllAssets[AssetIdx].bIsExploration == TRUE)
    {
        PC.UpdateAccomplishmentProgression('SALVAGECOUNT');
    }
    GLogger = Class'BioRemoteLogger'.static.GetLogger();
    if (AllAssets[AssetIdx].Type == EGAWAssetType.GAWAssetType_Modifier)
    {
        for (idx = 0; idx < AllAssets[AssetIdx].ModTargets.Length; idx++)
        {
            if (GLogger != None)
            {
                GLogger.SendPlayerEvent(112, "Modded Asset ID=" $ AllAssets[AssetIdx].ModTargets[idx].TargetID $ ", Mod Value=" $ AllAssets[AssetIdx].ModTargets[idx].Value, "", "", "", AllAssets[AssetIdx].ModTargets[idx].TargetID, AllAssets[AssetIdx].ModTargets[idx].Value, 0, 0);
            }
            UpdateGAWAsset(AllAssets[AssetIdx].ModTargets[idx].TargetID, AllAssets[AssetIdx].ModTargets[idx].Value, TRUE);
            MarkAssetAsNew(AllAssets[AssetIdx].ModTargets[idx].TargetID);
        }
    }
    for (idx = 0; idx < UnlockedGAWAssets.Length; idx++)
    {
        if (UnlockedGAWAssets[idx].Strength < 0)
        {
            UnlockedGAWAssets[idx].Strength = 0;
        }
    }
    if (GLogger != None)
    {
        GLogger.SendPlayerEvent(111, "", string(AllAssets[AssetIdx].Type), string(AllAssets[AssetIdx].SubType), AllAssets[AssetIdx].AssetName $ ", ID=" $ AllAssets[AssetIdx].Id $ "Current Strength =" $ AllAssets[AssetIdx].CurrentStrength, AllAssets[AssetIdx].Id, AllAssets[AssetIdx].CurrentStrength, 0, 0);
    }
    if (AllAssets[AssetIdx].bShowNotificationOnAward == TRUE)
    {
        if (AllAssets[AssetIdx].Type == EGAWAssetType.GAWAssetType_Salvage)
        {
            HintSystem.AddNotification_GalaxyAtWarSalvage();
        }
        else if (AllAssets[AssetIdx].Type == EGAWAssetType.GAWAssetType_Modifier)
        {
            if (AllAssets[AssetIdx].GUIName != 0)
            {
                HintSystem.AddNotification_GalaxyAtWarAsset(AllAssets[AssetIdx].GUIName);
            }
            for (idx = 0; idx < AllAssets[AssetIdx].ModTargets.Length; idx++)
            {
                Idx2 = AllAssets.Find('Id', AllAssets[AssetIdx].ModTargets[idx].TargetID);
                if (Idx2 != -1)
                {
                    HintSystem.AddNotification_GalaxyAtWarModifier(AllAssets[Idx2].GUIName);
                }
            }
        }
        else if (AllAssets[AssetIdx].Type == EGAWAssetType.GAWAssetType_Artifact)
        {
            HintSystem.AddNotification_GalaxyAtWarArtifact(AllAssets[AssetIdx].GUIName);
        }
        else if (AllAssets[AssetIdx].Type == EGAWAssetType.GAWAssetType_Intel)
        {
            HintSystem.AddNotification_GalaxyAtWarIntel(AllAssets[AssetIdx].GUIName);
        }
        else
        {
            HintSystem.AddNotification_GalaxyAtWarAsset(AllAssets[AssetIdx].GUIName);
        }
    }
    return TRUE;
}

public final function int GetTotalScore()
{
    return GetTotalStrengthByType(0);
}

public final function bool UpdateGAWAsset(int Id, int NewStrength, optional bool bAddToTotal = FALSE)
{
    local int idx;

    if (Id < 0)
    {
        return FALSE;
    }
    idx = UnlockedGAWAssets.Find('Id', Id);
    if (idx < 0)
    {
        return FALSE;
    }
    if (!bAddToTotal)
    {
        UnlockedGAWAssets[idx].Strength = NewStrength;
    }
    else
    {
        UnlockedGAWAssets[idx].Strength += NewStrength;
    }
    return TRUE;
}

public function OnUsed(Actor User)
{
    local bool bGaveResources;
    local SFXPawn_Player pPawn;
    local SFXInventoryManager InvManager;

    pPawn = SFXPawn_Player(User);
    if (pPawn == None)
    {
        return;
    }
    InvManager = SFXInventoryManager(pPawn.InvManager);
    if (InvManager == None)
    {
        return;
    }
    bGaveResources = InvManager.AwardResource(TreasureType, ResourcePercent, bUseAbsuluteAmount);
    if (!bGaveResources)
    {
        return;
    }
    ResourcePercent = 0;
    SetTargetable(FALSE);
    Used(User);
}

public event simulated function HandlePostBeginPlay()
{
    LogInternal("SFXTreasureUseModule: HandlePostBeginPlay", );
    Super(SFXSimpleUseModule).HandlePostBeginPlay();
    if (ResourcePercent <= 0 || HasBeenUsed())
    {
        SetTargetable(FALSE);
    }
}

public function SetTargetable(bool bTargetable, optional bool bSetTargetSave = FALSE)
{
    local ActorComponent Comp;
    local StaticMeshComponent oStaticMesh;
    local LinearColor EmissiveColor;
    local int nIndex;
    local MaterialInstanceConstant M;
    local MaterialInstanceConstant Instance;

    Super(SFXSelectionModule).SetTargetable(bTargetable);
    if (!bTargetable)
    {
        ResourcePercent = 0;
        foreach ModuleOwner.AllOwnedComponents(Class'ActorComponent', Comp)
        {
            oStaticMesh = StaticMeshComponent(Comp);
            if (oStaticMesh != None)
            {
                for (nIndex = 0; nIndex < oStaticMesh.Materials.Length; nIndex++)
                {
                    M = MaterialInstanceConstant(oStaticMesh.Materials[nIndex]);
                    if (M != None)
                    {
                        M.GetVectorParameterValue('Emissive_color', EmissiveColor);
                        if (M.Outer != ModuleOwner && EmissiveColor.A > 1.0)
                        {
                            Instance = new (ModuleOwner) Class'MaterialInstanceConstant';
                            Instance.SetParent(M);
                            EmissiveColor.A = EmissiveColor.A / float(10);
                            Instance.SetVectorParameterValue('Emissive_color', EmissiveColor);
                            oStaticMesh.SetMaterial(nIndex, Instance);
                        }
                    }
                }
            }
        }
    }
}

public event function bool IsDefaultActionPossible()
{
    return m_TargetTipText != ETargetTipText.TargetTipText_None && ResourcePercent > 0;
}
